<section class="next-page-banner"><div class="next-shell"><p><?= e($profile['name'] ?? SCHOOL_NAME) ?></p><h1><?= e($settings['home_news_title'] ?? $title) ?></h1></div></section>
<div class="next-shell next-archive">
    <div class="next-archive-toolbar"><form action="/berita" method="get"><label for="next-news-category"><?= e(PublicTheme::text($settings,'category')) ?></label><select id="next-news-category" name="category"><option value=""><?= e(PublicTheme::text($settings,'all_categories')) ?></option><?php foreach ($newsCategories ?? [] as $newsCategory): ?><option value="<?= e($newsCategory['slug']) ?>" <?= ($category ?? '') === $newsCategory['slug'] ? 'selected' : '' ?>><?= e($newsCategory['name']) ?></option><?php endforeach; ?></select><button type="submit" class="next-button next-button--primary"><?= e(PublicTheme::text($settings,'filter')) ?></button></form></div>
    <div class="next-archive-grid"><?php foreach ($news ?? [] as $item): ?><article class="next-archive-card"><a class="next-archive-image" href="/berita/<?= e($item['slug']) ?>"><?php if (!empty($item['image'])): ?><img src="/storage/<?= e($item['image']) ?>" alt="" loading="lazy" decoding="async"><?php endif; ?></a><div class="next-archive-body"><p class="next-byline"><?= e($item['category'] ?? '') ?> · <?= e(date('d M Y', strtotime($item['published_at'] ?? $item['created_at']))) ?></p><h2><a href="/berita/<?= e($item['slug']) ?>"><?= e($item['title']) ?></a></h2><p><?= e($item['excerpt'] ?? '') ?></p></div></article><?php endforeach; ?></div>
    <?php if (empty($news)): ?><p class="next-empty" role="status"><?= e(PublicTheme::text($settings,'empty')) ?></p><?php endif; ?>
    <?php if (!empty($pagination) && $pagination['total_pages'] > 1): ?><nav class="next-pagination" aria-label="Halaman berita"><?php for ($i = 1; $i <= (int) $pagination['total_pages']; $i++): ?><a href="?page=<?= $i ?>" <?= $i === (int) $pagination['current_page'] ? 'aria-current="page"' : '' ?>><?= $i ?></a><?php endfor; ?></nav><?php endif; ?>
</div>
